async function importMembers(file: File, onDone: (count: number) => void): Promise<void> {
  const rows = await parseCsv(file);
  try {
    for (const row of rows) {
      if (!row.email) throw new Error(`row ${row.line}: missing email`);
      await api.post("/members", row);
    }
    onDone(rows.length);
  } catch (err) {
    toast.error("Network error, please check your connection");
  }
}

async function removeMember(member: Member, onDone: () => void): Promise<void> {
  try {
